const { Command } = require('commander');
const program = new Command();

program
  .command('test [args...]')
  .allowUnknownOption(true)
  .helpOption(false)
  .action((args) => {
    console.log('Type of args:', typeof args);
    console.log('Args:', args);
    console.log('Args is array:', Array.isArray(args));
    if (args) console.log('Args content:', JSON.stringify(args));
  });

program.parseAsync(['node', 'test', 'init', '--ci']);
"
